html:
{% set logo = doc.company_logo or '/assets/wafd_one/images/wafd-almadinah-official.png' %}
<style>
@page { size:A4; margin:8mm 14mm; }
html,body,.print-format{margin:0!important;padding:0!important;background:#fff!important;}
.sheet{direction:rtl;font-family:Tahoma,Arial,sans-serif;color:#111;font-size:10.2px;line-height:1.55;box-sizing:border-box;height:274mm;overflow:hidden;padding:0 1mm;page-break-inside:avoid;}
.head{display:table;width:100%;table-layout:fixed;border-bottom:1px solid #b88a2a;padding-bottom:3mm;margin-bottom:4mm;}
.head-left,.head-center,.head-right{display:table-cell;vertical-align:middle;}
.head-left{width:34%;direction:rtl;text-align:left;font-size:8.8px;line-height:1.65;color:#555;}
.head-center{width:48%;text-align:center;}.head-center b{font-size:15px;}.head-center span{font-size:8.8px;color:#666;}
.head-right{width:18%;text-align:right;}.logo{width:24mm;height:25mm;object-fit:contain;}
h1{text-align:center;font-size:16px;text-decoration:underline;margin:2mm 0 4mm;}
p{margin:1.2mm 0;text-align:justify;}
.details{width:100%;border-collapse:collapse;margin:3mm 0;font-size:9.7px;}
.details td{border:1px solid #bbb;padding:2.2mm;vertical-align:top;}
.terms{border:1px solid #ccc;padding:2.5mm;margin-top:3mm;}
.sign{margin-top:5mm;text-align:center;page-break-inside:avoid;position:relative;height:49mm;overflow:visible;}
.manager-title{font-weight:700;line-height:1.6;}
.manager-name{font-weight:700;font-size:11px;position:absolute;z-index:2;top:25mm;left:0;right:0;text-align:center;}
.signature-overlay{position:absolute;left:50%;top:11mm;transform:translateX(-50%);width:57mm;height:24mm;object-fit:contain;z-index:3;}
.stamp-below{position:absolute;left:50%;top:31mm;transform:translateX(-50%);width:50mm;height:50mm;object-fit:contain;z-index:1;}
</style>
<div class='sheet'>
<div class='head'><div class='head-left'><div>المدينة المنورة — حي الملك فهد</div><div dir='ltr'>0500336989</div><div dir='ltr'>wafd.almadinah@gmail.com</div></div><div class='head-center'><b>شركة وفد المدينة لخدمات الإعاشة</b><br><span>WAFD AL-MADINAH CATERING SERVICES</span></div><div class='head-right'><img class='logo' src='{{ logo }}'></div></div>
<h1>تعهد والتزام إعاشة</h1>
<p>نحن <b>{{ doc.company_name or 'شركة وفد المدينة لخدمات الإعاشة' }}</b>، سجل تجاري رقم <b>{{ doc.company_cr or '7051832694' }}</b>، نتعهد بتقديم خدمات الإعاشة للمستفيدين في الفندق الموضح أدناه، وفق البيانات المعتمدة والاشتراطات الصحية والتنظيمية، مع ضمان جودة وسلامة الوجبات أثناء التجهيز والنقل والتسليم.</p>
<table class='details'>
<tr><td><b>رقم التعهد</b><br>{{ doc.name or '' }}</td><td><b>التاريخ</b><br>{{ doc.get_formatted('undertaking_date') if doc.undertaking_date else '' }}</td></tr>
<tr><td><b>المشروع</b><br>{{ doc.project or '' }}</td><td><b>الفندق</b><br>{{ doc.hotel or '' }}</td></tr>
<tr><td><b>البعثة أو العميل</b><br>{{ doc.mission or '' }}</td><td><b>عدد المستفيدين</b><br>{{ doc.beneficiary_count or 0 }}</td></tr>
<tr><td><b>الجنسية</b><br>{{ doc.nationality or '' }}</td><td><b>مدة الخدمة</b><br>{{ doc.get_formatted('start_date') if doc.start_date else '' }} — {{ doc.get_formatted('end_date') if doc.end_date else '' }}</td></tr>
<tr><td><b>الوجبات</b><br>{{ doc.meal_types or '' }}</td><td><b>موقع التوريد</b><br>{{ doc.supply_location or doc.hotel or '' }}</td></tr>
</table>
<div class='terms'><b>الشروط والملاحظات:</b><br><ol style='margin:1mm 5mm 0 0;padding:0'>
<li>تقديم الوجبات المتفق عليها وفق العدد ونوع الوجبة والفترة الموضحة في التعهد.</li>
<li>الالتزام بمواعيد تجهيز ونقل وتسليم الوجبات دون تأخير.</li>
<li>الالتزام باشتراطات سلامة الغذاء والنظافة والتعبئة والنقل والحفظ الحراري.</li>
<li>تسليم الوجبات في موقع التوريد المحدد وبالكميات المعتمدة.</li>
<li>تزويد الفندق بالمستندات النظامية المطلوبة عند الطلب.</li>
<li>للفندق التحقق من الكميات والحالة الظاهرية عند الاستلام وإثبات أي ملاحظة فوراً.</li>
<li>لا يُعتد بأي تعديل في العدد أو المواعيد إلا بعد اعتماده من الشركة.</li>
</ol>{% if doc.additional_terms or doc.service_notes %}<div><b>بنود إضافية:</b> {{ doc.additional_terms or doc.service_notes }}</div>{% endif %}</div>
<div class='sign'><div class='manager-title'>شركة وفد المدينة لخدمات الإعاشة<br>المدير العام</div>
{% if doc.include_signature and doc.signature_image %}<img class='signature-overlay' src='{{ doc.signature_image }}'>{% endif %}
<div class='manager-name'>نزار بن مذير بن ظفر</div>
{% if doc.include_stamp and doc.company_stamp %}<img class='stamp-below' src='{{ doc.company_stamp }}'>{% endif %}
</div></div>
